          "summary": "*Morris-Jones's Formulation:* Characterized India's system as a **\"one-party dominant system\"**, distinct from authoritarian one-party regimes because other parties were legally and practically free to compete, criticize, and mobilize, even though th",
          "details": [
            "*Morris-Jones's Formulation:* Characterized India's system as a **\"one-party dominant system\"**, distinct from authoritarian one-party regimes because other parties were legally and practically free to compete, criticize, and mobilize, even though they lacked systemic capability to dislodge the ruling party.",
            "*Rajni Kothari's Formulation:* Coined the classic term **\"The Congress System\"**. Congress operated as a vast, overarching **\"Party of Consensus\"** containing multiple internal ideological factions (Left, Right, Centrist). The opposition parties functioned not as alternatives to the government, but as **\"Parties of Pressure\"** acting on the marginal factions of Congress.",
            "*Nehruvian Accommodative Consensus:* Maintained internal democratic climate, tolerated dissent, preserved organizational elections, and co-opted emerging regional satraps (e.g., K. Kamaraj in Madras, B.C. Roy in Bengal, Y.B. Chavan in Maharashtra).",
            "*The 1967 Watershed (4th General Elections):* Congress lost power in eight major states across the Hindi heartland and South India (Tamil Nadu fell to DMK, West Bengal to United Front), forming a coalition in a ninth. This gave birth to the **Samyukta Vidhayak Dal (SVD)** coalition governments, the culture of political defections (*\"Aaya Ram, Gaya Ram\"*), and the first rural OBC peasant assertion ",
            "*De-institutionalisation under Indira Gandhi:* Indira Gandhi bypassed the Congress \"Syndicate\" (traditional organizational bosses), split the party in 1969, and substituted party organization with charismatic, personalized plebiscitary politics. Organizational elections were discontinued after 1972. Loyalty replaced merit and grass-roots mass base; regional satraps were systematically replaced by ",
            "*The Confrontational Dynamic:* Direct confrontation with judicial institutions, the opposition (JP Movement 1974\u201375), federal state governments, and the declaration of the National Emergency (1975\u20131977).",
            "*The 1989 Fracture:* The end of single-party parliamentary majorities. The rise of coalition governance at the Centre through three micro-phases:",
            "*The Federalisation of Governance:* Regional parties became kingmakers at the Centre, extracting ministerial portfolios, special financial packages, and veto power over economic and foreign policies."
          ]
