            "When different parties rule, the Centre-State channel becomes an arena for inter-party electoral combat, disguised as jurisdictional conflict.",
            "The **Sarkaria Commission (1988)** and **Punchhi Commission (2010)** observed that the constitutional design of Centre-State relations is fundamentally sound. The operational breakdowns, arbitrary dismissals of state governments, and conflicts over Governor's discretion were driven almost entirely by partisan political warfare rather than structural flaws in the constitutional text.",
            "**Stage I (1947\u20131967) \u2014 Hegemonic Consensus:** Coined by **Rajni Kothari** as the *\"Congress System\"*. The Congress operated as a broad \"party of consensus\" accommodating regional factions. Tall state leaders (K. Kamaraj, B.C. Roy, G.B. Pant) negotiated with Nehru on equal terms.",
            "**Stage II (1967\u20131989) \u2014 Confrontation & Centralised Decay:** Post-1967 Fourth General Elections, Congress lost power in 8 states (rise of Samyukta Vidhayak Dal coalitions). Under Indira Gandhi, internal party democracy was dismantled, resulting in severe political centralisation, politicisation of the Governor's office, and reckless deployment of Article 356 over 90 times. As **W.H. Morris-Jones*",
            "**Stage III (1989\u20132014) \u2014 Regional Hegemony & Coalition Prudence:** Marked by the hung parliaments and regional fragmentation. Regional satraps (TDP, DMK, AIADMK, TMC, JD(U), BJD) became indispensable coalition partners in the National Front, United Front, NDA, and UPA. This transformed the Centre from a commanding hegemon into a negotiated platform."
